@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_review_status_normative(test_workspace: dict) -> None:
    """
    Verify that changing the "normative" status of a correctly hashed item marks it as unreviewed.
    """
    assertion_context = test_workspace["graph"].get_item("ASN-CONTEXT")
    # Delete cached sha
    del assertion_context.sha256
    assertion_context._normative = True  # noqa: SLF001
    assert not test_workspace["graph"].get_review_status("ASN-CONTEXT")


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_review_status_edit_text(test_workspace: dict) -> None:
    """
    Verify that changing the text of a correctly hashed item sets its review status to false.
    """
    assert test_workspace["graph"].get_review_status("ASN-1")
    assertion_1 = test_workspace["graph"].get_item("ASN-1")
    # Delete cached sha
    del assertion_1.sha256
    assertion_1._text = "Alice knows Carol"  # noqa: SLF001
    assert not test_workspace["graph"].get_review_status("ASN-1")


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_review_status_edit_reference(test_workspace: dict) -> None:
    """
    Verify that changing the reference contents of a correctly hashed item sets its review status to false.
    """
    assert test_workspace["graph"].get_review_status("DOC-1")
    with test_workspace["reference"].open("w") as file:
        file.write("Carol: 603 776 2323")

    edited_ref = dotstop.LocalFileReference(str(test_workspace["reference"])).resolve()
    # Delete cached sha
    del test_workspace["items"][-1].sha256
    test_workspace["items"][-1]._resolved_references = [edited_ref]  # noqa: SLF001
    assert not test_workspace["graph"].get_review_status("DOC-1")


