@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_link_status_edit_parent(test_workspace: dict) -> None:
    """
    Verify that changing the parent of a non-suspect link marks it as `SUSPECT`.
    """
    test_graph = test_workspace["graph"]
    assert test_graph.get_link_status("ASN-1", "DOC-1") == dotstop.LinkStatus.LINKED
    assertion_1 = test_graph.get_item("ASN-1")
    del assertion_1.sha256
    assertion_1._text = "Alice knows Dave"  # noqa: SLF001
    assert test_graph.get_link_status("ASN-1", "DOC-1") == dotstop.LinkStatus.SUSPECT


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_link_status_edit_child(test_workspace: dict) -> None:
    """
    Verify that changing the child of a non-suspect link marks it as `SUSPECT`.
    """
    test_graph = test_workspace["graph"]
    assert test_graph.get_link_status("ASN-1", "DOC-1") == dotstop.LinkStatus.LINKED
    document_1 = test_graph.get_item("DOC-1")
    del document_1.sha256
    document_1._text = "Alice is in Carol's Address Book"  # noqa: SLF001
    assert test_graph.get_link_status("ASN-1", "DOC-1") == dotstop.LinkStatus.SUSPECT


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_get_link_status_edit_reference(test_workspace: dict) -> None:
    """
    Verify that changing a child reference of a non-suspect link marks it as `SUSPECT`.
    """
    assert (
        test_workspace["graph"].get_link_status("ASN-1", "DOC-1")
        == dotstop.LinkStatus.LINKED
    )
    del test_workspace["items"][-1].sha256
    with test_workspace["reference"].open("w") as file:
        file.write("Carol: 603 776 2323")
        test_workspace["items"][-1]._resolved_references = [  # noqa: SLF001
            dotstop.LocalFileReference(str(test_workspace["reference"])).resolve()
        ]
    assert (
        test_workspace["graph"].get_link_status("ASN-1", "DOC-1")
        == dotstop.LinkStatus.SUSPECT
    )


