@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_descendants_subgraph(test_workspace: dict) -> None:
    subgraph = test_workspace["graph"].descendants_subgraph(["ASN-1", "ASN-2"])
    # Should contain all items bar EXP-1 and ASN-CONTEXT.
    print([item.name for item in test_workspace["graph"].items])
    print([item.name for item in subgraph.items])
    for item in test_workspace["graph"].items:
        if item.name == "EXP-1" or item.name == "ASN-CONTEXT":
            assert item not in subgraph.items
        else:
            assert item in subgraph.items
